use super::*;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use std::sync::{atomic::{AtomicUsize,Ordering},Mutex};
use semio_framework_value_native_decoding::native_decoding::{OriginalEffectReply,OriginalEffectReplyComplete};
struct Source{error:Mutex<Option<ValueError>>,calls:AtomicUsize,recoveries:AtomicUsize}
impl NativeValueSource for Source{
 fn as_source(&self)->&dyn NativeValueSource{self}fn tree_kind(&self)->Option<NativeTreeKind>{None}
 fn query_schema_key<'reply,'source>(&'source self,_:crate::record::NativeSchemaKeySource,effect:&mut crate::RetainedAllocationEffect<'_>,reply:NativeSourceKeyReply<'reply,'source>)->Result<NativeSourceKeyReplyComplete<'reply>,ValueError>{self.calls.fetch_add(1,Ordering::SeqCst);assert!(effect.performed(1).unwrap());let error=self.error.lock().unwrap().take().unwrap();let _recorded=reply.complete(Err(error));panic!("after recorded original schema key")}
 fn recover_schema_key<'reply,'source>(&'source self,_:crate::record::NativeSchemaKeySource,_:&mut crate::RetainedAllocationEffect<'_>,reply:NativeSourceKeyReply<'reply,'source>)->Result<NativeSourceKeyReplyComplete<'reply>,ValueError>{self.recoveries.fetch_add(1,Ordering::SeqCst);Ok(reply.pending())}
 fn query_scalar<'reply>(&self,_:NativeScalarQuery,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,NativeSourceScalar,ValueError>)->Result<OriginalEffectReplyComplete<'reply,NativeSourceScalar,ValueError>,ValueError>{self.calls.fetch_add(1,Ordering::SeqCst);assert!(effect.performed(1).unwrap());let error=self.error.lock().unwrap().take().unwrap();let _recorded=reply.complete(Err(error));panic!("after recorded original Source reply")}
 fn recover_scalar<'reply>(&self,_:NativeScalarQuery,_:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,NativeSourceScalar,ValueError>)->Result<OriginalEffectReplyComplete<'reply,NativeSourceScalar,ValueError>,ValueError>{self.recoveries.fetch_add(1,Ordering::SeqCst);Ok(reply.pending())}
}
#[test]fn actual_source_error_remains_in_its_borrowed_reply_through_unwind(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️scalar-query.json")).unwrap();let error=ValueError::new(ValueRefusalKind::Canceled,"original scalar Source refusal".to_owned());let pointer=error.message.as_ptr();let source=Source{error:Mutex::new(Some(error)),calls:AtomicUsize::new(0),recoveries:AtomicUsize::new(0)};let mut reply=None;let stock=serde_json::json!({"items":32,"copyBytes":4096,"capacityBytes":4096,"releaseBytes":4096,"depth":8,"fuel":32,"maximumTurns":32});let mut bank=EffectBank::new(Wallet::from_profile(&stock));let grant=bank.loan(1,std::mem::size_of::<Option<Result<NativeSourceScalar,ValueError>>>());let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _=bank.run::<(),ValueError>(grant,1,|effect|{let token=OriginalEffectReply::borrow(&mut reply).unwrap();let _=source.query_scalar(NativeScalarQuery::Boolean,effect,token).unwrap();unreachable!()});}));assert!(interrupted.is_err());assert_eq!(source.calls.load(Ordering::SeqCst),law["calls"].as_u64().unwrap()as usize);assert_eq!(reply.as_ref().unwrap().as_ref().unwrap_err().message.as_ptr(),pointer);let(poll,actual)=bank.run(grant,1,|_|{assert!(reply.is_some());crate::RetainedWorkPoll::Complete(crate::RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:0})});let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("recorded reply recovery remained pending")};assert!(turn.result.is_ok());assert_eq!(turn.work,0);assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));assert_eq!(source.recoveries.load(Ordering::SeqCst),0);assert_eq!(reply.take().unwrap().unwrap_err().message.as_ptr(),pointer);bank.post(RetainedCloneProgress::default(),grant,(0,0));}

#[test]fn original_schema_key_reply_keeps_owned_error_during_unwind(){let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️key-query.json")).unwrap();let error=ValueError::new(ValueRefusalKind::Canceled,"original key Source refusal".to_owned());let pointer=error.message.as_ptr();let source=Source{error:Mutex::new(Some(error)),calls:AtomicUsize::new(0),recoveries:AtomicUsize::new(0)};let mut reply=None;let stock=serde_json::json!({"items":32,"copyBytes":4096,"capacityBytes":4096,"releaseBytes":4096,"depth":8,"fuel":32,"maximumTurns":32});let mut bank=EffectBank::new(Wallet::from_profile(&stock));let grant=bank.loan(1,std::mem::size_of::<Option<Result<NativeSourceKey,ValueError>>>());let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _=bank.run::<(),ValueError>(grant,1,|effect|{let token=NativeSourceKeyReply::borrow(&source,&mut reply).unwrap();let _=source.query_schema_key(crate::record::NativeSchemaKeySource::Record(0),effect,token).unwrap();unreachable!()});}));assert!(interrupted.is_err());assert_eq!(source.calls.load(Ordering::SeqCst),law["sourceCalls"].as_u64().unwrap() as usize);assert_eq!(reply.as_ref().unwrap().as_ref().err().unwrap().message.as_ptr(),pointer);let(poll,actual)=bank.run(grant,1,|_|crate::RetainedWorkPoll::Complete(crate::RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:0}));let crate::RetainedWorkPoll::Complete(turn)=poll else{panic!("recorded reply recovery remained pending")};assert!(turn.result.is_ok());assert_eq!(turn.work,0);assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));assert_eq!(source.recoveries.load(Ordering::SeqCst),law["recoverCalls"].as_u64().unwrap() as usize);assert_eq!(reply.take().unwrap().err().unwrap().message.as_ptr(),pointer);bank.post(RetainedCloneProgress::default(),grant,(0,0));}

#[test]fn schema_key_vacant_seed_fields_stay_individually_bounded(){let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️key-query.json")).unwrap();let template=key_frame::NativeSchemaKeyFrame::<Source>::seed_template();let count=template.field_parts().unwrap();assert_eq!(count,law["seedParts"].as_u64().unwrap() as usize);let mut target=std::mem::MaybeUninit::<key_frame::NativeSchemaKeyFrame<Source>>::uninit();for index in 0..count{let bytes=unsafe{key_frame::NativeSchemaKeyFrame::<Source>::seed_part_size(&mut target,index)}.unwrap();assert!(bytes<=law["maxPartCopy"].as_u64().unwrap() as usize,"seed part {index} requires {bytes} bytes")}assert!(unsafe{key_frame::NativeSchemaKeyFrame::<Source>::seed_part_size(&mut target,count)}.is_none());}
